 enum class Kind:uint8_t{ReadAdc,ClearScheduler,ArmScheduler,ClockInitialize,ReadTick};enum class Block:uint8_t{None,NotBound,Inactive,NeedsInterrupt,UnsupportedMode};struct Result{unsigned clocks=0;bool returned=false;Block blocked=Block::None;};struct Range{uint32_t begin,end;};inline static constexpr std::array<Range,4>CodeRanges{{{0x5cc,0x5ee},{0x9aa,0x9b6},{0x388c,0x3a20},{0x4444,0x4454}}};
 bool bindBootResources(ControllerDeviceState&d,const uint8_t*image,size_t size){if(bound_||active()||!image||size!=49728||!d.hasImmutableCapacity(CodeRanges.size()))return false;for(auto r:CodeRanges)for(auto a=r.begin;a<r.end;++a)if(d.readResource(a)!=image[a])return false;for(auto r:CodeRanges)if(!d.protectImmutableVerified(r.begin,r.end,image+r.begin))return false;bound_=&d;return true;}
